import{createLogger,logError}from"#internal/logging.js";import{runtimeWait,storedProjection,turnPosition}from"#harness/session-machine/view.js";import{cancelRun,getRun,getWorld,resumeHook}from"#internal/workflow/runtime.js";import{getBlockingWorkflowToolRuns}from"#harness/workflow-tool-runs.js";import{WORKFLOW_CANCELLATION_SETTLE_MS}from"#execution/tools/workflow/cancellation-policy.js";import{isTaskWorkflowTargetGone}from"#execution/tasks/workflow-target.js";const log=createLogger(`execution.stop-runs`);function waitedCallRuns(e){try{let t=runtimeWait(e.state)?.event.turnId??turnPosition(storedProjection(e.state)).turnId;return getBlockingWorkflowToolRuns(e.state,t).map(e=>({ends:!0,run:e.address}))}catch(t){return logError(log,`failed to read the workflow tool calls a cancelled turn waits on`,t,{sessionId:e.sessionId}),[]}}async function stopRuns(e,t,n={}){let r=(await Promise.all(e.map(async e=>({target:e,told:await tell(e.run,t)})))).filter(({target:e})=>e.ends),i=n.waitForEnd===!1?[]:await runsStillRunning(r.filter(({told:e})=>e).map(({target:e})=>e.run.runId)),a=r.filter(({told:e})=>!e).map(({target:e})=>e.run.runId);return(await Promise.all([...a,...i].map(async e=>await cancelOutright(e,t.reason)?[e]:[]))).flat()}async function tell(e,t){try{return await resumeHook(e.hookToken,t),!0}catch(t){return isTaskWorkflowTargetGone(t)||logError(log,`failed to tell a run to stop; cancelling it outright`,t,{runId:e.runId}),!1}}async function runsStillRunning(e){let t=e,n=Date.now()+WORKFLOW_CANCELLATION_SETTLE_MS;for(;t.length>0&&Date.now()<n;)t=(await Promise.all(t.map(async e=>({runId:e,live:await isRunLive(e)})))).filter(({live:e})=>e).map(({runId:e})=>e),t.length>0&&await new Promise(e=>setTimeout(e,250));return t}async function isRunLive(e){try{let t=await getRun(e).status;return t===`pending`||t===`running`}catch(e){return!isTaskWorkflowTargetGone(e)}}async function cancelOutright(e,t){try{return await cancelRun(await getWorld(),e,{cancelReason:t}),!0}catch(t){return isTaskWorkflowTargetGone(t)||logError(log,`failed to cancel a run; it may run to completion`,t,{runId:e}),!1}}export{stopRuns,waitedCallRuns};